    void get_NAF_W(int W, Giant& a, std::vector<int16_t>& res, bool compress)
    {
        giant exp = allocgiant(a.size() + 1);
        uint32_t* giant_n = exp->n;
        memcpy(giant_n, a.data(), a.size()*sizeof(uint32_t));
        exp->sign = a.size();

        giant cur = allocgiant(2);
        int nafwMask = (1 << W) - 1;
        int nafwBit = (1 << (W - 1));
        int bit = 0;
        while (!isZero(exp))
        {
            if (bitval(exp, bit))
            {
                cur->n[0] = exp->n[0];
                cur->sign = 1;
                if (exp->sign > 1 && exp->n[1] != 0 && bit + W >= 32)
                {
                    cur->n[1] = exp->n[1];
                    cur->sign = 2;
                }
                gshiftright(bit, cur);
                res.push_back((int16_t)(cur->n[0] & nafwMask));
                if (res.back() & nafwBit)
                    res.back() -= (int16_t)(nafwMask + 1);
                itog(-res.back(), cur);
                gshiftleft(bit, cur);
                addg(cur, exp);
                bit += (compress ? W : 1);
            }
            else
            {
                res.push_back(0);
                bit++;
            }
            if (bit >= 32 && exp->sign > 0)
            {
                bit -= 32;
                exp->n++;
                exp->sign--;
            }
        }
        free(cur);
        exp->n = giant_n;
        free(exp);
    }

    int get_DAC_S_d(int e, int start, int end, int *maxlen)
    {
        int minlen = *maxlen;
        int mind = -1;
        if (start < 1)
            start = 1;
        if (end > e)
            end = e;
        for (int d = start; d < end; d++)
        {
            if (gcd(d, e) != 1)
                continue;
            int te = e;
            int td = d;
            int len = 0;
            while (td != 0 && len < minlen)
            {
                if (te/2 < td)
                    td = te - td;
                else if ((te & 1) == 0 && td < te/4)
                {
                    len += 2;
                    te = te/2;
                }
                else
                {
                    len++;
                    te = te - td;
                }
            }
            if (minlen > len)
            {
                minlen = len;
                mind = d;
            }
        }
        *maxlen = minlen;
        return mind;
    }

    int get_DAC_M_d(int e, int start, int end, int *maxlen)
    {
        int minlen = *maxlen;
        int mind = -1;
        if (start < e/2 + 1)
            start = e/2 + 1;
        if (end > e)
            end = e;
        for (int d = start; d < end; d++)
        {
            if (gcd(d, e) != 1)
                continue;
            int te = e - d;
            int td = d - te;
            int len = 2;
            while (td != te && len < minlen)
            {
                if (td < te)
                {
                    int t = td;
                    td = te;
                    te = t;
                }
                if (100*td <= 296*te || ((td & 1) == 1 && (te & 1) == 0))
                {
                    len++;
                    td = td - te;
                }
                else if ((td & 1) == (te & 1))
                {
                    len += 2;
                    td = (td - te) >> 1;
                }
                else
                {
                    len += 2;
                    td = td >> 1;
                }
            }
            if (minlen > len)
            {
                minlen = len;
                mind = d;
            }
        }
        *maxlen = minlen;
        return mind;
    }

